fn solve(a: i8, b: i8, c: i8) -> i8 {
    let mut v = [a as i32, b as i32, c as i32];
    v.sort();
    let x = v[0];
    let y = v[1];
    let z = v[2];

    // Try targets t >= z. Each operation adds total sum +2, so total increments sum must be even.
    // Small search is enough because values are <= 50 and we can always reach by increasing.
    let mut best = i32::MAX;

    for t in z..=z + 200 {
        let dx = t - x;
        let dy = t - y;
        let dz = t - z;
        let total = dx + dy + dz;
        if total % 2 != 0 {
            continue;
        }
        let dmax = dx.max(dy).max(dz);
        let ops = (total / 2).max(dmax);
        if ops < best {
            best = ops;
        }
    }

    best as i8
}